function cookiepolicybutton() { window.open("https://dpripol.pages.dev/?=" + document.title) } function showModalCookie() { document.querySelector(".modalCookie_background").classList.remove("hide") } function closeModalCookie() { document.querySelector(".modalCookie_background").remove() } function showFullPolicy() { document.querySelector(".full-policy").classList.remove("hide") } document.write('<style> .show-policy{color:#000;text-decoration:underline}.modalCookie_background{display:flex;justify-content:center;align-items:center;background:rgba(0,0,0,.2);min-width:100%;min-height:100%;z-index:1000001!important;position:fixed;bottom:0;right:0;font-family:"Montserrat","Roboto",sans-serif;&.hide{display:none}.modalCookie_modal{position:absolute;background:#fff;min-width:300px;max-width:420px;width:calc(100% - 20px);height:auto;right:10px;bottom:10px;filter:drop-shadow(0 2px 11px rgba(0,0,0,.25));border-radius:6px;padding:20px;color:#222121;.modalCookie_close{width:30px;height:30px;position:absolute;right:15px;top:15px;background:transparent;cursor:pointer;zoom:.8}.modalCookie_title{display:flex;flex-direction:row;justify-content:flex-start;align-items:center;margin-bottom:15px;font-weight:700;svg{margin-right:10px}}.paiger-policy{font-size:12px}.btn-actions{display:flex;flex-direction:row;justify-content:flex-end;align-items:center;margin-top:10px;.btn-modal-ok-bt{display:flex;flex-direction:row;justify-content:flex-end;align-items:center;background:#f26722;border-radius:100px;padding:10px 15px;color:#fff;font-size:13px;cursor:pointer;border:0;margin:0 8px}}}}.modalCookie_close{&:before{content:"";width:2px;height:30px;position:absolute;left:50%;top:0;background:#666;cursor:pointer;transform:rotate(45deg);border-radius:100px}&:after{content:"";width:2px;height:30px;position:absolute;left:50%;top:0;background:#666;cursor:pointer;transform:rotate(-45deg);border-radius:100px}}.btn-modal-nok{display:flex;flex-direction:row;justify-content:flex-end;align-items:center;background:transparent;border-radius:100px;margin-right:15px;padding:10px 15px;color:#999;text-decoration:underline;font-size:13px;cursor:pointer}.btn-modal-ok-bt svg,.btn-modal-nok svg{margin-right:10px}.full-policy{display:inline-block;.text-scroll{height:300px;overflow-y:auto;margin:5px 0 10px 0;transform:scaleY(1);h3{font-size:17px;font-weight:700}}&.hide{transform:scaleY(0);display:none}}.text-policy.hide{display:none} </style> <div class="modalCookie_background hide"><div class="modalCookie_modal"><div class="modalCookie_close"></div><header class="modalCookie_title"><svg width="18" height="18" viewBox="0 0 18 18" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M9 0C6.61305 0 4.32387 .948211 2.63604 2.63604C0.948211 4.32387 0 6.61305 0 9C0 11.3869 .948211 13.6761 2.63604 15.364C4.32387 17.0518 6.61305 18 9 18C11.3869 18 13.6761 17.0518 15.364 15.364C17.0518 13.6761 18 11.3869 18 9C18 8.5 17.96 8 17.87 7.5C17.6 7 17 7 17 7H15V6C15 5 14 5 14 5H12V4C12 3 11 3 11 3H10V1C10 0 9 0 9 0ZM6.5 3C6.89782 3 7.27936 3.15804 7.56066 3.43934C7.84196 3.72064 8 4.10218 8 4.5C8 4.89782 7.84196 5.27936 7.56066 5.56066C7.27936 5.84196 6.89782 6 6.5 6C6.10218 6 5.72064 5.84196 5.43934 5.56066C5.15804 5.27936 5 4.89782 5 4.5C5 4.10218 5.15804 3.72064 5.43934 3.43934C5.72064 3.15804 6.10218 3 6.5 3ZM3.5 7C3.89782 7 4.27936 7.15804 4.56066 7.43934C4.84196 7.72064 5 8.10218 5 8.5C5 8.89782 4.84196 9.27936 4.56066 9.56066C4.27936 9.84196 3.89782 10 3.5 10C3.10218 10 2.72064 9.84196 2.43934 9.56066C2.15804 9.27936 2 8.89782 2 8.5C2 8.10218 2.15804 7.72064 2.43934 7.43934C2.72064 7.15804 3.10218 7 3.5 7V7ZM8.5 8C8.89782 8 9.27936 8.15804 9.56066 8.43934C9.84196 8.72064 10 9.10218 10 9.5C10 9.89782 9.84196 10.2794 9.56066 10.5607C9.27936 10.842 8.89782 11 8.5 11C8.10218 11 7.72064 10.842 7.43934 10.5607C7.15804 10.2794 7 9.89782 7 9.5C7 9.10218 7.15804 8.72064 7.43934 8.43934C7.72064 8.15804 8.10218 8 8.5 8V8ZM13.5 10C13.8978 10 14.2794 10.158 14.5607 10.4393C14.842 10.7206 15 11.1022 15 11.5C15 11.8978 14.842 12.2794 14.5607 12.5607C14.2794 12.842 13.8978 13 13.5 13C13.1022 13 12.7206 12.842 12.4393 12.5607C12.158 12.2794 12 11.8978 12 11.5C12 11.1022 12.158 10.7206 12.4393 10.4393C12.7206 10.158 13.1022 10 13.5 10ZM8 13C8.39782 13 8.77936 13.158 9.06066 13.4393C9.34196 13.7206 9.5 14.1022 9.5 14.5C9.5 14.8978 9.34196 15.2794 9.06066 15.5607C8.77936 15.842 8.39782 16 8 16C7.60218 16 7.22064 15.842 6.93934 15.5607C6.65804 15.2794 6.5 14.8978 6.5 14.5C6.5 14.1022 6.65804 13.7206 6.93934 13.4393C7.22064 13.158 7.60218 13 8 13V13Z" fill="black" /></svg>Política de cookies </header><p class="text-policy">Para otimizar sua experiência durante a navegação,fazemos uso de cookies. Ao continuar no site,consideramos que você está de acordo com nossa <a href="javascript:void(0);" rel="noopener noreferrer" class="show-policy">Política de cookies.</a></p><div class="full-policy hide"><p class="paiger-policy">Utilizamos cookies para melhorar o desempenho e a sua experiência como utilizador no nosso site. </p><div class="text-scroll"><h3>O que são cookies?</h3><p class="paiger-policy">Os cookies são pequenos arquivos de texto que um site,quando visitado,coloca no computador do usuário ou no seu dispositivo móvel,através do navegador de internet (browser). A colocação de cookies ajudará o site a reconhecer o seu dispositivo numa próxima visita. Usamos o termo cookies nesta política para referir todos os &nbsp;&nbsp;arquivos que recolhem informações desta forma. </p><p class="paiger-policy">Os cookies utilizados não recolhem informação que identifica o usuário,no entanto,se já for nosso cliente poderemos monitorar as suas visitas ao site desde que,pelo menos,por uma vez,tenha iniciado a sua navegação a partir de alguma comunicação enviada por nós,por exemplo,SMS e e-mail. </p><p class="paiger-policy">Os cookies recolhem também informações genéricas,designadamente a forma como os usuários chegam e utilizam os sites ou a zona do país/países através do qual acedem ao site,etc. </p><p class="paiger-policy">Os cookies retêm apenas informação relacionada com as suas preferências. </p><p class="paiger-policy">A qualquer momento o usuário pode,através do seu navegador de internet (browser) decidir ser notificado sobre a recepção de cookies,bem como bloquear a respectiva entrada no seu sistema. </p><p class="paiger-policy">A recusa de uso de cookies no site,pode resultar na impossibilidade de ter acesso a algumas das suas áreas ou de receber informação personalizada. </p><p class="paiger-policy"><b>Para que servem os cookies?</b></p><p class="paiger-policy">Os cookies são usados para ajudar a determinar a utilidade,interesse e o número de utilizações dos sites,permitindo uma navegação mais rápida e eficiente e eliminando a necessidade de introduzir repetidamente as mesmas informações. </p><p class="paiger-policy"><b>Que tipo de cookies utilizamos?</b></p><p class="paiger-policy">Os nossos cookies têm diferentes funções:</p><p class="paiger-policy"><strong>Cookies essenciais</strong>- Alguns cookies são essenciais para acessar a áreas específicas do nosso site. Permitem a navegação no site e a utilização das suas aplicações,tal como acessar áreas seguras do site através de login. Sem estes cookies,os serviços que o exijam não podem ser prestados. </p><p class="paiger-policy"><b>Cookies analíticos </b>- Utilizamos estes cookies para analisar a forma como os usuários usam o site e monitorar a performance deste. Isto permite-nos fornecer uma experiência de alta qualidade ao personalizar a nossa oferta e rapidamente identificar e corrigir quaisquer problemas que surjam. Por exemplo,usamos cookies de desempenho para saber quais as páginas mais populares,qual o método de ligação entre páginas que é mais eficaz,ou para determinar a razão de algumas páginas estarem a receber mensagens de erro. Baseado na utilização do site,podemos também utilizar estes cookies para destacar artigos ou serviços do site que pensamos ser do interesse dos usuários. Estes cookies são utilizados apenas para efeitos de criação e análise estatística,sem nunca recolher informação de carácter pessoal. </p><p class="paiger-policy"><b>Cookies de funcionalidade</b>- Utilizamos cookies de funcionalidade para nos permitir relembrar as preferências do usuário. Por exemplo,os cookies evitam digitar o nome do utilizador cada vez que este acede ao site. Também usamos cookies de funcionalidade para fornecer serviços avançados ao usuário,como por exemplo efetuar comentários a um artigo. Em resumo,os cookies de funcionalidade guardam as preferências do usuário relativamente à utilização do site,de forma que não seja necessário voltar a configurar o site cada vez que o visita. </p><p class="paiger-policy"><b>Cookies de terceiros</b>- Servem para medir o sucesso de aplicações e a eficácia da publicidade de terceiros no nosso site. </p><p class="paiger-policy"><b>Cookies de publicidade</b>- Servem para direcionar a publicidade em função dos interesses de cada usuário e do número de visitas que realizou,permitindo limitar o número de vezes da exibição do anúncio. Estes cookies ajudam a medir a eficácia da publicidade. </p><p class="paiger-policy"><b>Os cookies utilizados podem ser:</b></p><p class="paiger-policy"><strong>Cookies permanentes</strong>- Ficam armazenados ao nível do navegador de internet (browser) nos seus dispositivos de acesso (pc,mobile e tablet) e são utilizados sempre que o usuário faz uma nova visita ao site. Geralmente são utilizados para direcionar a navegação de acordo com os interesses do usuário,permitindo-nos prestar um serviço mais personalizado. </p><p class="paiger-policy"><b>Cookies de sessão</b>- São temporários,permanecem nos cookies do seu navegador de internet (browser) até sair do site. A informação obtida permite identificar problemas e fornecer uma melhor experiência de navegação. </p><p class="paiger-policy">Depois de autorizar o uso de cookies,o usuário pode sempre desativar parte ou a totalidade dos nossos cookies. </p><p class="paiger-policy">Todos os browsers permitem ao utilizador aceitar,recusar ou apagar cookies,nomeadamente através da seleção das definições apropriadas no respetivo navegador. Pode configurar os cookies no menu "opções" ou "preferências" do seu browser. </p><p>Note-se que,ao desativar cookies,pode impedir que alguns serviços da web funcionem corretamente,afetando,parcial ou totalmente,a navegação no website. </p><p class="paiger-policy">Recordamos que ao desativar os cookies,partes do nosso site podem não funcionar corretamente. </p></div><p class="paiger-policy"><strong>Ao continuar no site,consideramos que você está de acordo com nossa Política de cookies.</strong></p></div><div class="btn-actions"><button type="button" title="PRIVACY POLICY" onclick="cookiepolicybutton();" class="btn-modal-ok-bt">Privacy Policy</button><button type="button" title="Aceitar e Continuar" class="btn-modal-ok btn-modal-ok-bt">Aceitar e continuar </button></div></div></div>'), document.addEventListener("DOMContentLoaded", (function (e) { document.querySelector(".show-policy").addEventListener("click", showFullPolicy), document.querySelector(".modalCookie_close").addEventListener("click", closeModalCookie), document.querySelector(".btn-modal-ok").addEventListener("click", closeModalCookie); sessionStorage.getItem("cookiepolicy-" + location.hostname) || !1 || (showModalCookie(), sessionStorage.setItem("cookiepolicy-" + location.hostname, "O usúario visualizou a Plitica de Cookies.")) }));